def _controller(*, state: StatusState = StatusState.IDLE, unattached: bool = False):
    c = object.__new__(AppController)
    entry = _SessionEntry(SessionInfo(pid=42, session_id="s", cwd=_CWD, started_at=0))
    entry.state = state
    entry.unattached = unattached
    c._sessions = {42: entry}
    c._session_id_to_pid = {"s": 42}
    c._settings = Settings()
    c._busy_shells = set()
    return c, entry


def _scan(
    controller: AppController,
    *,
    busy: bool = False,
    wm_class: str = "com.microsoft.VSCode",
    focused_title: str = "",
) -> None:
    shells = [TerminalShell(pid=7, cwd=_CWD, busy=busy)]
    windows = [
        {"pid": 1, "wm_class": wm_class, "focus": False, "title": "x - other - Visual Studio Code"}
    ]
    if focused_title:
        windows.append({"pid": 1, "wm_class": wm_class, "focus": True, "title": focused_title})
    with (
        patch("claude_dashboard.controller.config.IS_LINUX", True),
        patch("claude_dashboard.platform.linux._list_windows_dbus", return_value=windows),
        patch("claude_dashboard.controller.scan_terminal_shells", return_value=shells),
    ):
        controller._check_terminal_activity()


def _run_command(controller: AppController, **kwargs) -> None:
    """A command seen running at one scan and gone by the next."""
    _scan(controller, busy=True, **kwargs)
    _scan(controller, busy=False, **kwargs)


class TestCommandFinished:
    def test_seen_running_then_done_marks_ready_and_keeps_guard(self):
        c, entry = _controller()
        entry.state_cleared_from = "working"
        _run_command(c)
        assert entry.state == StatusState.READY
        assert entry.state_cleared_from == "working"

    def test_command_never_seen_running_does_not_signal(self):
        """ls, cd, an empty Enter: over before any scan sees them."""
        c, entry = _controller()
        _scan(c)
        _scan(c)
        assert entry.state == StatusState.IDLE

    def test_still_running_shows_arrow_not_ready(self):
        c, entry = _controller()
        _scan(c, busy=True)
        _scan(c, busy=True)
        assert entry.has_terminal_activity is True
        assert entry.state == StatusState.IDLE

    def test_closed_terminal_does_not_signal(self):
        c, entry = _controller()
        _scan(c, busy=True)
        with (
            patch("claude_dashboard.controller.config.IS_LINUX", True),
            patch(
                "claude_dashboard.platform.linux._list_windows_dbus",
                return_value=[{"pid": 1, "wm_class": "com.microsoft.VSCode"}],
            ),
            patch("claude_dashboard.controller.scan_terminal_shells", return_value=[]),
        ):
            c._check_terminal_activity()
        assert entry.state == StatusState.IDLE

    def test_dismissed_stale_working_stays_blocked_through_terminal_ready(self):
        """OTEL keeps reporting WORKING after the user cleared it. A terminal
        command finishing must show READY, not hand the row back to WORKING,
        and dismissing that READY must keep WORKING blocked."""
        c, entry = _controller(state=StatusState.WORKING)
        c._is_stopped_sandbox = lambda e: False  # type: ignore[method-assign]
        stale_working = SessionState(state=StatusState.WORKING, host_name="h", project="p")

        _dismiss_state(entry)
        _run_command(c)
        c._apply_otel_state(pid=42, session_state=stale_working)
        assert entry.state == StatusState.READY

        _dismiss_state(entry)
        c._apply_otel_state(pid=42, session_state=stale_working)
        assert entry.state == StatusState.IDLE
        assert entry.state_cleared_from == "working"

    @pytest.mark.parametrize(
        "state", [StatusState.WORKING, StatusState.PERMISSION_REQUIRED, StatusState.AWAITING_INPUT]
    )
    def test_non_idle_state_untouched(self, state):
        c, entry = _controller(state=state)
        _run_command(c)
        assert entry.state == state

    def test_ghost_row_untouched(self):
        c, entry = _controller(unattached=True)
        _run_command(c)
        assert entry.state == StatusState.IDLE


class TestCommandStartedClearsReady:
    def test_new_command_clears_ready_and_guards_it(self):
        c, entry = _controller(state=StatusState.READY)
        _scan(c, busy=True)
        assert entry.state == StatusState.IDLE
        assert entry.state_cleared_from == "ready"

    def test_command_already_running_does_not_clear_later_ready(self):
        """Only the start clears; READY arriving mid-command stays."""
        c, entry = _controller()
        _scan(c, busy=True)
